title: Parse coupon codes
description:
Adds `parseCoupon(code)` for SAVE<n> (percent) and OFF<cents> (amount) codes.

--- src/coupons.js (modified, +7 −0)
@@ -9,3 +9,10 @@ export function amountOff(subtotalCents, offCents) {
   if (!Number.isInteger(offCents) || offCents < 0) throw new RangeError(`offCents must be a non-negative integer: ${offCents}`);
   return Math.max(0, subtotalCents - offCents);
 }
+
+// "SAVE10" -> { kind: "percent", value: 10 }; "OFF500" -> { kind: "amount", value: 500 }.
+export function parseCoupon(code) {
+  const m = /^(SAVE|OFF)(\d{1,5})$/.exec(String(code).trim().toUpperCase());
+  if (!m) return null;
+  return m[1] === "SAVE" ? { kind: "percent", value: Number(m[2]) } : { kind: "amount", value: Number(m[2]) };
+}

